"""Build the Aether portfolio page and source-derived public API reference."""
from pathlib import Path
import html
import json
import re

ROOT = Path(__file__).resolve().parent
E = lambda value: html.escape(str(value), quote=True)

def build_page(page, project):
    body = '''<main id="main" class="aether-detail wrap"><a class="back-link" href="index.html#work">← Back to the portfolio</a>
<header class="ad-head"><p class="eyebrow">Blender material authoring · In development</p><h1>Aether</h1><p class="ad-lede">A material authoring and baking workflow built around geometry, procedural materials, and ordinary texture maps.</p><p>I use Aether to build the structure behind a surface in Blender, capture its material data, and see how it holds up in a game engine. The construction stays editable; the exported result can be a conventional set of maps.</p><nav class="ad-links"><a class="button" href="aether-gallery.html">View the render gallery →</a><a href="aether-api/index.html">Aether API reference →</a><a href="https://github.com/sharpen3d/Aether">Aether on GitHub ↗</a></nav></header>
<section class="ad-gallery"><div><p class="eyebrow">Recent work · Rendered in Plush</p><h2>Materials and props</h2><p>The gallery brings together the results of the current authoring workflow, including material variations, wall plates, and an interactive comparison of flat shading, parallax occlusion mapping, and near-field surfels.</p><a href="aether-gallery.html">Explore the gallery →</a></div><div class="ad-thumbs"><a href="aether-gallery.html#exterior-materials"><img src="assets/aether-gallery/mat_05_grass_meadow.jpg" alt="Grass meadow rendered in Plush" loading="lazy"><span>Grass meadow</span></a><a href="aether-gallery.html#interior-materials"><img src="assets/aether-gallery/mat_36_beadboard_wainscot.jpg" alt="Painted beadboard rendered in Plush" loading="lazy"><span>Beadboard</span></a><a href="aether-gallery.html#props"><img src="assets/aether-gallery/obj_03_wall_plates.jpg" alt="Wall plates rendered in Plush" loading="lazy"><span>Wall plates</span></a></div></section>
<section class="ad-section"><div><p class="eyebrow">Background</p><h2>Where it started</h2></div><div><p>I started Aether in 2025. It now brings together two workflows I had been building separately. xBake focused on getting mesh information into usable texture maps: source and target setup, baking, and organizing output. TextureLab explored making materials in a texture-space scene, using Blender’s nodes and geometry to build the surface itself.</p><p>Aether carries both ideas forward. I can bake position, normal, curvature, AO and material IDs from a source mesh, use those inputs while authoring, then capture the result into a consistent map set. It has grown into a broader workflow for seamless materials and object surfaces.</p><div class="ad-history"><figure><a href="images/xbake-cover.png"><img src="images/xbake-cover.png" alt="Earlier xBake geometry, normal map and textured model" loading="lazy"></a><figcaption>Earlier xBake output</figcaption></figure><figure><a href="images/darkroom.png"><img src="images/darkroom.png" alt="Earlier TextureLab material workflow" loading="lazy"></a><figcaption>Earlier TextureLab workspace</figcaption></figure></div></div></section>
<section class="ad-section"><div><p class="eyebrow">Authoring</p><h2>Building the surface</h2></div><div><p>For a repeating material I work in an orthographic canvas. A brick, a joint, a blade of grass, or a piece of peeling paint can be actual geometry, combined with shader detail and Geometry Nodes. Aether repeats the evaluated, seeded geometry across the edges so the construction tiles; the same seed gives me a stable result to edit.</p><p>A shared material wrapper exposes the channels for capture. Layers can participate in individual maps and cast AO independently. The top-down capture produces base color, tangent normal, roughness, metallic, AO, opacity and height; presets can pack those outputs for a target engine. Height records physical scale for uses such as POM.</p></div></section>
<section class="ad-interface"><header><p class="eyebrow">Blender interface</p><h2>The working interface</h2><p>These are real captures of the Aether 1.0.24 development workspace in Blender 5.2.3, captured in November 2026. Open an image to inspect the controls.</p></header><div class="ad-ui-grid"><figure><a href="assets/aether-ui/workspace.png"><img src="assets/aether-ui/workspace.png" alt="Aether workspace with a UV canvas, 3D receiver, and editable shader graph" loading="lazy"></a><figcaption><strong>Workspace</strong> · The texture-space canvas, 3D receiver, and shader graph stay visible together. This example uses live original-surface data to drive a material.</figcaption></figure><figure><a href="assets/aether-ui/output-controls.png"><img src="assets/aether-ui/output-controls.png" alt="Aether sidebar showing Tile Geometry, Layer Contributions, Texture Output, preview and export controls" loading="lazy"></a><figcaption><strong>Layers and output</strong> · The sidebar controls map participation and AO casting, map selection, preview resolution, formats, and final export. Tile Geometry and Scene Setup are visible here too.</figcaption></figure></div><p>Source Map Baking has its own panel for choosing a target, UV map, output folder, and optional high-resolution source. The Shader and Geometry Nodes editors also expose source maps, live surface data and material tools.</p></section>
<section class="ad-section"><div><p class="eyebrow">Development workflow</p><h2>Working through MCP</h2></div><div><p>I use a separate Blender development extension, Devkit, to connect my local assistant to an open Blender session. The MCP server is an intermediary: it discovers an authenticated session and routes requests to Blender’s main thread. Blender still owns the open file, scene data, evaluation, renders, and UI.</p><p>The assistant can inspect the scene and extension state, search Aether’s source-derived API, call operators, run Blender Python, inspect the UI, and reload extension code. That lets me work through an actual material or test while extending the tools: inspect the scene, make a change, render and review, then adjust the implementation without restarting the whole session.</p><p>The named tools are entry points, not a replacement for Blender Python. This is a personal development workflow; Aether’s ordinary material and export workflow remains usable in stock Blender without Devkit or my custom Blender build.</p><a href="aether-api/index.html">Browse the Aether API →</a></div></section>
<section class="ad-section"><div><p class="eyebrow">Current work</p><h2>From capture to engine</h2></div><div><p>The regular PBR workflow and packed exports are in use. I’m also testing near-field relief: Aether captures depth slices and compiles surface samples for Plush to draw as surfels near the camera, with POM on the host surface farther away. That path is experimental; the gallery shows the current result and the data behind it.</p><p>Object surface authoring, region metadata for trims and decals, and live camera preview are also areas I’m continuing to develop. The renderer-specific preview is optional; it doesn’t replace the file-backed export.</p><nav class="ad-links"><a class="button" href="aether-gallery.html">View the gallery →</a><a href="aether-api/index.html">API reference →</a></nav></div></section></main>'''
    doc=page('Aether — material authoring and baking', 'Aether is my Blender workflow for geometry-based material authoring, baking and export.', body, active='Work', body_class='project-page')
    doc=doc.replace('</head>', '<link rel="stylesheet" href="assets/aether-ui/aether.css?v=1"></head>', 1)
    (ROOT/'aether.html').write_text(doc)

def build_api():
    data=json.loads((ROOT/'content/aether-api.json').read_text())
    root=ROOT/'aether-api'; (root/'operators').mkdir(parents=True,exist_ok=True); (root/'settings').mkdir(exist_ok=True)
    ops=sorted(data['operators'],key=lambda x:x['id']); groups=data['settings']
    slug=lambda s: re.sub(r'[^a-z0-9]+','-',s.lower()).strip('-')
    nav={'stamp':'Aether '+data['aether_version']+' development','sections':[{'t':'Start','g':[{'a':'','i':[{'n':'API home','u':'index.html','s':'Aether API reference'}]}]},{'t':'Operators','g':[{'a':'Blender operators','i':[{'n':o['id'],'u':'operators/'+slug(o['id'])+'.html','s':o.get('label','')+' · '+o.get('status','')} for o in ops]}]},{'t':'Settings','g':[{'a':'RNA properties','i':[{'n':g,'u':'settings/'+slug(g)+'.html','s':'Aether settings for '+g,'m':[[p['name'],slug(p['name'])] for p in props]} for g,props in groups.items()]}]}]}
    (root/'nav.js').write_text('window.PLUSH_API = '+json.dumps(nav,ensure_ascii=False)+';\n')
    def layout(title, current, content):
        prefix='../' if '/' in current else ''
        site='../../' if prefix else '../'
        return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>{E(title)} · Aether API</title><link rel="stylesheet" href="{site}assets/aether-api/style.css"><link rel="stylesheet" href="{site}assets/authorship.css?v=2"></head><body class="api" data-root="{site}" data-api="{prefix}" data-page="{E(current)}"><header class="bar"><div class="project-identity"><a class="mark" href="{site}aether.html"><span>Aether</span></a><a class="creator-link" href="https://lukestilson.com/">by Luke Stilson</a></div><nav aria-label="Main navigation"><a href="{site}aether.html">Aether</a><a href="{site}aether-gallery.html">Gallery</a><a class="on" href="{prefix}index.html">API Reference</a><a href="https://github.com/sharpen3d/Aether">GitHub ↗</a></nav></header><div class="api-layout"><aside class="side"><button class="api-browse-toggle" id="api-browse-toggle" type="button" aria-controls="api-browser-content" aria-expanded="true" hidden>Browse API</button><div class="side-content" id="api-browser-content"><div class="search"><input id="q" type="search" aria-label="Search API operators and settings" placeholder="Search operators and settings" autocomplete="off" spellcheck="false"><kbd>/</kbd></div><nav id="tree" aria-label="API"></nav></div></aside><main class="doc">{content}<footer class="stamp">Aether {E(data['aether_version'])} · source-derived development snapshot</footer></main></div><script src="{prefix}nav.js"></script><script src="{site}assets/aether-api/api.js"></script><footer class="author-footer" data-author-credit><div class="author-inner"><p>© 2026 <a href="https://lukestilson.com/">Luke Stilson</a></p><nav aria-label="Author links"><a href="{site}index.html">Portfolio ↗</a><a href="https://github.com/sharpen3d">GitHub ↗</a></nav></div></footer></body></html>'''
    home='''<h1>API reference</h1><p>Reference for Aether’s Blender operators and RNA settings, generated from the add-on’s operator docstrings and property descriptions.</p><p>Enable Aether before calling <code>bpy.ops</code>. Operators can require a particular scene, selection, mode or editor context; check each entry. File writes are outside Blender Undo. Internal Python helpers are not a supported public API.</p><div class="table"><table><thead><tr><th scope="col">Reference</th><th scope="col">Contents</th></tr></thead><tbody><tr><td>Operators</td><td>Identifiers, context, effects, limits and operator properties</td></tr><tr><td>Settings</td><td>RNA properties, descriptions, declared defaults and ranges</td></tr></tbody></table></div><p>Use the sidebar to browse or search. Experimental and placeholder entries are labeled; placeholders do not provide a working action.</p><p><a href="api.json">Download the machine-readable reference</a> · <a href="../aether.html">About Aether</a></p>'''
    (root/'index.html').write_text(layout('API reference','index.html',home)); (root/'api.json').write_text(json.dumps(data,indent=2,ensure_ascii=False)+'\n')
    def properties(props):
        if not props:return '<p>No operator properties documented.</p>'
        rows=[]
        for p in props:
            detail=[]
            for k in ('default','min','max','subtype','unit','size'):
                if k in p:detail.append(k+': '+str(p[k]))
            if isinstance(p.get('items'), list):
                detail.append('choices: '+', '.join(str(item[0]) for item in p['items'] if item))
            rows.append(f'<tr id="{slug(p["name"])}"><td><code>{E(p["name"])}</code></td><td>{E(p.get("type",""))}</td><td>{E(p.get("description", ""))}<br><small>{E(" · ".join(detail))}</small></td></tr>')
        return '<div class="table"><table><thead><tr><th scope="col">Property</th><th scope="col">Type</th><th scope="col">Description and declaration</th></tr></thead><tbody>'+''.join(rows)+'</tbody></table></div>'
    for op in ops:
        path='operators/'+slug(op['id'])+'.html'; desc=op.get('description',''); paragraphs=''.join('<p>'+E(p).replace('\n','<br>')+'</p>' for p in desc.split('\n\n') if p.strip())
        txt=f'<h1>{E(op["id"])}</h1><p class="meta">{E(op.get("label",""))} · {E(op.get("status","current"))}</p><div class="code" data-lang="Python"><pre><code>bpy.ops.{E(op["id"])}(**properties)</code></pre></div>{paragraphs}<h2>Properties</h2>{properties(op.get("properties",[]))}<h2>Source</h2><p><code>{E(op.get("source",""))}:{E(op.get("line",""))}</code></p>'
        (root/path).write_text(layout(op['id'],path,txt))
    for group,props in groups.items():
        path='settings/'+slug(group)+'.html';txt=f'<h1>{E(group)}</h1><p>Declared Aether RNA properties for <code>{E(group)}</code>.</p>{properties(props)}';(root/path).write_text(layout(group,path,txt))
